#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    k = k % n; // 处理k>=n的情况
    if (k == 0) {
        for (int i = 0; i < n; i++) {
            if (i > 0) cout << " ";
            cout << a[i];
        }
        cout << endl;
        return 0;
    }

    // 三次反转法
    // 1. 反转整个数组
    reverse(a.begin(), a.end());
    // 2. 反转前k个元素
    reverse(a.begin(), a.begin() + k);
    // 3. 反转后n-k个元素
    reverse(a.begin() + k, a.end());

    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << a[i];
    }
    cout << endl;
    return 0;
}

